// OpenIDTransactionCreateBulk is the builder for creating many OpenIDTransaction entities in bulk.
type OpenIDTransactionCreateBulk struct {
	config
	err      error
	builders []*OpenIDTransactionCreate
	conflict []sql.ConflictOption
}

// Save creates the OpenIDTransaction entities in the database.
func (oitcb *OpenIDTransactionCreateBulk) Save(ctx context.Context) ([]*OpenIDTransaction, error) {
	if oitcb.err != nil {
		return nil, oitcb.err
	}
	specs := make([]*sqlgraph.CreateSpec, len(oitcb.builders))
	nodes := make([]*OpenIDTransaction, len(oitcb.builders))
	mutators := make([]Mutator, len(oitcb.builders))
	for i := range oitcb.builders {
		func(i int, root context.Context) {
			builder := oitcb.builders[i]
			builder.defaults()
			var mut Mutator = MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
				mutation, ok := m.(*OpenIDTransactionMutation)
				if !ok {
					return nil, fmt.Errorf("unexpected mutation type %T", m)
				}
				if err := builder.check(); err != nil {
					return nil, err
				}
				builder.mutation = mutation
				var err error
				nodes[i], specs[i] = builder.createSpec()
				if i < len(mutators)-1 {
					_, err = mutators[i+1].Mutate(root, oitcb.builders[i+1].mutation)
				} else {
					spec := &sqlgraph.BatchCreateSpec{Nodes: specs}
					spec.OnConflict = oitcb.conflict
					// Invoke the actual operation on the latest mutation in the chain.
					if err = sqlgraph.BatchCreate(ctx, oitcb.driver, spec); err != nil {
						if sqlgraph.IsConstraintError(err) {
							err = &ConstraintError{msg: err.Error(), wrap: err}
						}
					}
				}
				if err != nil {
					return nil, err
				}
				mutation.id = &nodes[i].ID
				if specs[i].ID.Value != nil {
					id := specs[i].ID.Value.(int64)
					nodes[i].ID = int(id)
				}
				mutation.done = true
				return nodes[i], nil
			})
			for i := len(builder.hooks) - 1; i >= 0; i-- {
				mut = builder.hooks[i](mut)
			}
			mutators[i] = mut
		}(i, ctx)
	}
	if len(mutators) > 0 {
		if _, err := mutators[0].Mutate(ctx, oitcb.builders[0].mutation); err != nil {
			return nil, err
		}
	}
	return nodes, nil
}

